  "task.tpl": "तैयार कार्य",
  "task.tpl.sub": "किसी तैयार कार्य को शुरुआती बिंदु के रूप में चुनें, फिर उसे संपादित करें या ऊपर दिए गए फ़ील्ड में अपना कार्य लिखें:",
  "ph.task": "उदा. रोज़ पैदल चलने से हृदय स्वास्थ्य पर पड़ने वाले लाभों पर सरल वैज्ञानिक गहराई में एक पूरा लेख लिखें...",
  "hint.task": "💡 कार्य जितना सटीक होगा, परिणाम उतना ही निकट आएगा। \"इसमें मेरी मदद करो\" जैसी अस्पष्ट पंक्तियों से बचें।",
