  "role.tpl.sub": "कोई तैयार पहचान चुनें और बाकी फ़ील्ड अपने आप भर जाएँगे — फिर कोई भी फ़ील्ड संपादित करें या ऊपर दिए बॉक्स में अपनी भूमिका लिखें:",
  "ph.role": "उदा. डिजिटल मार्केटिंग विशेषज्ञ, सॉफ़्टवेयर इंजीनियर, शिक्षक, भाषा संपादक",
  "hint.role": "मॉडल को एक पेशेवर पहचान देने से उत्तर अधिक गहरे और अधिक सटीक हो जाते हैं।",
  "sec.context": "संदर्भ और पृष्ठभूमि",
